export type RowBindingWire = { "kind": "value", value: string | number | boolean | null, } | { "kind": "list", values: Array<string | number | boolean | null>, } | { "kind": "unspecialised", detail: string, } | { "kind": "inexpressible", detail: string, };

export type RowCombinator = "all" | "any" | "not";

export type RowCommit = { entityType: string, id: string, expected: EntityRow | null, write: RowCommitWrite, };

export type RowCommitWrite = { "kind": "keep" } | { "kind": "put", row: EntityRow, } | { "kind": "delete" };

export type RowCompareOp = "==" | "!=" | "<" | "<=" | ">" | ">=";

export type RowDirection = "asc" | "desc";

export type RowIdPage = { ids: Array<string>, total: number, };

export type RowLeafKind = "compare" | "member" | "hasElement" | "contains" | "isNull";

export type RowNearest = { field: string, vector: Array<number>, k: number, };

export type RowOperator = "==" | "!=" | "<" | "<=" | ">" | ">=" | "member" | "hasElement" | "contains";

export type RowOrder = { field: string, direction: RowDirection, };

export type RowOrderableFields = { "kind": "every-field" } | { "kind": "listed", fields: Array<string>, };

export type RowPage = { rows: Array<EntityRow>, total: number, };

export type RowPredicate = { kind: "compare", field: string, op: RowCompareOp, value: FieldValue } | { kind: "member", field: string, values: Array<FieldValue> } | { kind: "hasElement", field: string, value: FieldValue } | { kind: "contains", field: string, text: string, caseSensitive: boolean } | { kind: "isNull", field: string, isNull: boolean } | { kind: "all", of: Array<RowPredicate> } | { kind: "any", of: Array<RowPredicate> } | { kind: "not", of: RowPredicate } | { kind: "const", value: boolean }

export type RowProjection = "rows" | "ids";

export type RowQuery = { policy?: RowPredicate, filter?: RowPredicate, order?: RowOrder, offset?: number, limit?: number, total?: RowTotalMode, 
/**
 * The nearest `k` rows by cosine similarity among those `policy` and `filter` admit (EXEC-FETCH-2). Excludes
 * `order`, `offset` and `limit`.
 */
nearest?: RowNearest, };

export type RowSetRef = { entityType: string, ids: Array<string>, total: number, query: RowQuery, };

export type RowTotalMode = "exact" | "none";

export type RowValueKind = "string" | "number" | "boolean" | "date" | "null";

export type RowWriteBatch = { ops: Array<RowWriteOp>, onFailure: RowWriteFailureMode, };

export type RowWriteFailureMode = "atomic" | "stop";

export type RowWriteOp = { "kind": "create", entityType: string, data: EntityRow, } | { "kind": "upsert", entityType: string, data: EntityRow, } | { "kind": "update", entityType: string, id: string, data: EntityRow, guard?: RowPredicate, } | { "kind": "rekey", entityType: string, id: string, newId: string, guard?: RowPredicate, } | { "kind": "delete", entityType: string, id: string, guard?: RowPredicate, };

export type RowWriteOutcome = { "kind": "created", row: EntityRow, } | { "kind": "updated", row: EntityRow, before?: EntityRow, } | { "kind": "deleted", before?: EntityRow, } | { "kind": "not-found" } | { "kind": "duplicate-id" } | { "kind": "refused" } | { "kind": "failed", message: string, } | { "kind": "rolled-back" };

export type RunTick = { trait: string, tick: string, };

export type SeedWire = { trait: string, event: string, };

export type ServerEffectCode = "not-found" | "no-row-key" | "duplicate-id" | "denied";

export type ServerEffectKind = "set" | "persist" | "call-service" | "http" | "fetch" | "fetch-stream" | "ref" | "deref" | "swap" | "atomic" | "emit" | "substrate";

export type ServerEffectResult = { effect: ServerEffectKind, action?: string, entityType?: string, 
/**
 * The namespaced operator (`memory/store`) — only on `ServerEffectKind::Substrate`.
 */
name?: NamespacedEffectName, data?: EntityRow | ServerBatchSummary | EventPayloadValue, success: boolean, 
/**
 * `true` when a persist failed because an access policy rejected it — never
 * serialized as `false` (the wire type is the TS literal `true`, not `bool`).
 */
denied?: true, error?: string, 
/**
 * Coded failure reason for a persist that resolved no target row, or created on a taken id.
 */
code?: ServerEffectCode, 
/**
 * What an `http` effect reached, `"<METHOD> <origin><path>"`; only on `ServerEffectKind::Http`.
 */
target?: string, 
/**
 * The declared `emit.failure` event a failed effect was routed to (the kernel fired it, so the failure is handled); absent when it declares none.
 */
routed?: string, };

export type ServerProgressWire = { "status": "done", response: EventResponse, } | { "status": "await", flight: number, requests: Array<PendingRequestWire>, };

export type Settled<T, E> = { "ok": T } | { "error": E };

export type SnapshotWire = { states: JsonObject, ambiguousTraits: Array<AmbiguousTrait>, theme: ResolvedTheme, canvasTheme: CanvasTheme, motion: ResolvedMotion, };

export type StatefulLegWire = { orbital: string, leg: EventRequest, awaiting: Array<AwaitingTrait>, };

export type StoreListing = { enabled: boolean, entries: Array<StoredName>, };

export type StoredName = { service: string, name: string, };

export type StreamFramingWire = "sse" | "jsonLines";

export type SubstrateFailureWire = { message: string, errors: Array<JsonValue>, };

export type TabAction = "click" | "focus" | "type";

export type TabApply = { elementId: string, styles: Array<TabStyle>, label?: string | null, };

export type TabAsk = { "kind": "list" } | { "kind": "open", url: string, active: boolean, } | { "kind": "close", tab: number, } | { "kind": "navigate", tab: number, url: string, } | { "kind": "command", tab: number, command: TabCommand, } | { "kind": "awaitReady", tab: number, timeoutMs: number, } | { "kind": "watch", watchId: string, match: string, selector: string, fields: Array<TabField>, deliver: TabDelivery, } | { "kind": "unwatch", watchId: string, } | { "kind": "capture", tab: number, format: TabImageFormat, quality?: number | null, };

export type TabCommand = { "kind": "query", selector: string, fields: Array<TabField>, limit?: number | null, waitMs?: number | null, } | { "kind": "watch", watchId: string, selector: string, fields: Array<TabField>, } | { "kind": "unwatch", watchId: string, } | { "kind": "apply" } & TabApply | { "kind": "applyMany", items: Array<TabApply>, } | { "kind": "act", elementId: string, action: TabAction, text?: string | null, };

export type TabDelivery = { orbital: string, trait: string, event: string, };

export type TabFailure = { kind: TabFailureKind, message: string, };

export type TabFailureKind = "unavailable" | "not-ready" | "not-found" | "invalid" | "failed";

export type TabField = { name: string, selector?: string | null, attr?: string | null, resolve?: boolean, template?: string | null, required?: boolean, };

export type TabImageFormat = "png" | "jpeg";

export type TabStyle = { property: string, value: string, };

export type TraceEffectsWire = { effects: Array<EffectTraceWire>, emitted: Array<EmittedEffectWire>, writes: Array<EntityWriteWire>, entity: JsonValue, };

export type TraitFrom = { trait: string, from: string, event?: string, };

export type TraitRef = { name: string, 
/**
 * `X` has rendered content in some orbital after a seeded INIT.
 */
resolved: boolean, 
/**
 * `X` renders only once an overlay-open transition fires.
 */
overlayOnly: boolean, };

export type TraitSnapshot = { state: string, entity: JsonValue }

export type TransitionHop = { trait: string, from: string, to: string, event: string, 
/**
 * The arm that fired, by its position among the state's arms for the event (declaration order).
 */
firedArm?: number, 
/**
 * `true` when the fired arm's guard held; absent for an unguarded arm.
 */
guardResult?: boolean, effects: Array<HopEffect>, 
/**
 * What a verifier judges the hop's `@ensures` on; present only when the kernel records each step's entity
 * after its effects (`set_record_entity_after`, EXEC-STEP-10).
 */
observed?: HopObservation, };

export type TransitionRejection = { code: TransitionRejectionCode, trait?: string, from?: string, event?: string, statesDeclaringEvent?: Array<string>, transition?: string, guard?: unknown, 
/**
 * `effect-failed`: the failure's message.
 */
error?: string, };

export type TransitionRejectionCode = "no-matching-transition" | "guard-rejected" | "no-dispatchable-traits" | "not-an-external-input" | "inbound-only-event" | "effect-failed";

export type Viewer = { 
/**
 * Stable subject identifier: the ownership key.
 */
id: string, 
/**
 * A token may carry no email or name, or carry it as null (owner ruling 2026-10-24).
 */
email?: string | null, name?: string | null, 
/**
 * Compared against a policy's allowed roles.
 */
role?: string, permissions?: Array<string>, claims: Array<Claim>, };

export type WriteCapabilities = { guards: GuardCapabilities, conditional: boolean, returnsRow: boolean, stopRuns: boolean, atomicBatch: boolean, rekey?: boolean, 
/**
 * The host commits rows the kernel decided, compare-and-commit in one transaction (EXEC-STORE-5); it then
 * holds no write semantics and the kernel runs every write form itself.
 */
commitRows?: boolean, };

const isRecord = (v: JsonValue | undefined): v is JsonObject => typeof v === 'object' && v !== null && !Array.isArray(v);

function checkBusEventSource(v: JsonValue | undefined): boolean {
  return (isRecord(v) && (v["orbital"] === undefined || typeof v["orbital"] === 'string') && (v["orbitalId"] === undefined || v["orbitalId"] !== undefined) && (v["trait"] === undefined || typeof v["trait"] === 'string') && (v["traitId"] === undefined || v["traitId"] !== undefined) && (v["eventId"] === undefined || v["eventId"] !== undefined) && (v["transition"] === undefined || typeof v["transition"] === 'string') && (v["tick"] === undefined || typeof v["tick"] === 'string') && (v["fromBridge"] === undefined || typeof v["fromBridge"] === 'boolean') && (v["dispatched"] === undefined || typeof v["dispatched"] === 'boolean') && (v["originClientId"] === undefined || typeof v["originClientId"] === 'string') && (v["pendingKey"] === undefined || typeof v["pendingKey"] === 'string') && (v["persistSuccess"] === undefined || typeof v["persistSuccess"] === 'boolean'));
}

function checkClientEffect(v: JsonValue | undefined): boolean {
  return ((Array.isArray(v) && v.length === 3 && v[0] === "render-ui" && typeof v[1] === 'string' && (v[2] !== undefined || v[2] === null)) || (Array.isArray(v) && v.length === 2 && v[0] === "navigate" && typeof v[1] === 'string') || (Array.isArray(v) && v.length === 3 && v[0] === "navigate" && typeof v[1] === 'string' && ((isRecord(v[2]) && Object.values(v[2]).every((e) => typeof e === 'string')) || v[2] === null)) || (Array.isArray(v) && v.length === 4 && v[0] === "navigate" && typeof v[1] === 'string' && ((isRecord(v[2]) && Object.values(v[2]).every((e) => typeof e === 'string')) || v[2] === null) && checkNavigateOptions(v[3])) || (Array.isArray(v) && v.length === 1 && v[0] === "navigate-back"));
}

function checkClientEffectByTrait(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["traitName"] === 'string' && checkClientEffect(v["effect"]) && (v["event"] === undefined || typeof v["event"] === 'string') && (v["fromState"] === undefined || typeof v["fromState"] === 'string') && (v["callsitePayload"] === undefined || v["callsitePayload"] !== undefined) && (v["repaint"] === undefined || checkRepaintReason(v["repaint"])));
}

function checkEmittedEvent(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["event"] === 'string' && (v["payload"] === undefined || v["payload"] !== undefined) && (v["source"] === undefined || checkBusEventSource(v["source"])));
}

function checkEventResponse(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["success"] === 'boolean' && typeof v["transitioned"] === 'boolean' && (isRecord(v["states"]) && Object.values(v["states"]).every((e) => typeof e === 'string')) && (Array.isArray(v["emittedEvents"]) && v["emittedEvents"].every((e) => checkEmittedEvent(e))) && (v["data"] === undefined || (isRecord(v["data"]) && Object.values(v["data"]).every((e) => (Array.isArray(e) && e.every((e) => e !== undefined))))) && (v["dataRefs"] === undefined || (isRecord(v["dataRefs"]) && Object.values(v["dataRefs"]).every((e) => checkRowSetRef(e)))) && (v["entityByTrait"] === undefined || (isRecord(v["entityByTrait"]) && Object.values(v["entityByTrait"]).every((e) => e !== undefined))) && (v["clientEffects"] === undefined || (Array.isArray(v["clientEffects"]) && v["clientEffects"].every((e) => checkClientEffect(e)))) && (v["clientEffectsByTrait"] === undefined || (Array.isArray(v["clientEffectsByTrait"]) && v["clientEffectsByTrait"].every((e) => checkClientEffectByTrait(e)))) && (v["effectResults"] === undefined || (Array.isArray(v["effectResults"]) && v["effectResults"].every((e) => checkServerEffectResult(e)))) && (v["guardFailed"] === undefined || typeof v["guardFailed"] === 'string') && (v["rejections"] === undefined || (Array.isArray(v["rejections"]) && v["rejections"].every((e) => checkTransitionRejection(e)))) && (v["cascadeTruncated"] === undefined || (Array.isArray(v["cascadeTruncated"]) && v["cascadeTruncated"].every((e) => typeof e === 'string'))) && (v["transitions"] === undefined || (Array.isArray(v["transitions"]) && v["transitions"].every((e) => checkTransitionHop(e)))) && (v["error"] === undefined || typeof v["error"] === 'string'));
}

function checkHopEffect(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["type"] === 'string' && (Array.isArray(v["args"]) && v["args"].every((e) => e !== undefined)) && checkHopEffectStatus(v["status"]) && (v["error"] === undefined || typeof v["error"] === 'string'));
}

function checkHopEffectStatus(v: JsonValue | undefined): boolean {
  return (v === "executed" || v === "failed" || v === "skipped");
}

function checkHopObservation(v: JsonValue | undefined): boolean {
  return (isRecord(v) && v["payload"] !== undefined && v["entityBefore"] !== undefined && v["entityAfter"] !== undefined);
}

function checkNavigateOptions(v: JsonValue | undefined): boolean {
  return (isRecord(v) && (v["crumb"] === undefined || typeof v["crumb"] === 'string'));
}

function checkRepaintReason(v: JsonValue | undefined): boolean {
  return v === "rows-changed";
}

function checkRowCompareOp(v: JsonValue | undefined): boolean {
  return (v === "==" || v === "!=" || v === "<" || v === "<=" || v === ">" || v === ">=");
}

function checkRowDirection(v: JsonValue | undefined): boolean {
  return (v === "asc" || v === "desc");
}

function checkRowNearest(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["field"] === 'string' && (Array.isArray(v["vector"]) && v["vector"].every((e) => typeof e === 'number')) && typeof v["k"] === 'number');
}

function checkRowOrder(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["field"] === 'string' && checkRowDirection(v["direction"]));
}

function checkRowPredicate(v: JsonValue | undefined): boolean {
  return ((isRecord(v) && v["kind"] === "compare" && typeof v["field"] === 'string' && checkRowCompareOp(v["op"]) && v["value"] !== undefined) || (isRecord(v) && v["kind"] === "member" && typeof v["field"] === 'string' && (Array.isArray(v["values"]) && v["values"].every((e) => e !== undefined))) || (isRecord(v) && v["kind"] === "hasElement" && typeof v["field"] === 'string' && v["value"] !== undefined) || (isRecord(v) && v["kind"] === "contains" && typeof v["field"] === 'string' && typeof v["text"] === 'string' && typeof v["caseSensitive"] === 'boolean') || (isRecord(v) && v["kind"] === "isNull" && typeof v["field"] === 'string' && typeof v["isNull"] === 'boolean') || (isRecord(v) && v["kind"] === "all" && (Array.isArray(v["of"]) && v["of"].every((e) => checkRowPredicate(e)))) || (isRecord(v) && v["kind"] === "any" && (Array.isArray(v["of"]) && v["of"].every((e) => checkRowPredicate(e)))) || (isRecord(v) && v["kind"] === "not" && checkRowPredicate(v["of"])) || (isRecord(v) && v["kind"] === "const" && typeof v["value"] === 'boolean'));
}

function checkRowQuery(v: JsonValue | undefined): boolean {
  return (isRecord(v) && (v["policy"] === undefined || checkRowPredicate(v["policy"])) && (v["filter"] === undefined || checkRowPredicate(v["filter"])) && (v["order"] === undefined || checkRowOrder(v["order"])) && (v["offset"] === undefined || typeof v["offset"] === 'number') && (v["limit"] === undefined || typeof v["limit"] === 'number') && (v["total"] === undefined || checkRowTotalMode(v["total"])) && (v["nearest"] === undefined || checkRowNearest(v["nearest"])));
}

function checkRowSetRef(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["entityType"] === 'string' && (Array.isArray(v["ids"]) && v["ids"].every((e) => typeof e === 'string')) && typeof v["total"] === 'number' && checkRowQuery(v["query"]));
}

function checkRowTotalMode(v: JsonValue | undefined): boolean {
  return (v === "exact" || v === "none");
}

function checkServerEffectCode(v: JsonValue | undefined): boolean {
  return (v === "not-found" || v === "no-row-key" || v === "duplicate-id" || v === "denied");
}

function checkServerEffectKind(v: JsonValue | undefined): boolean {
  return (v === "set" || v === "persist" || v === "call-service" || v === "http" || v === "fetch" || v === "fetch-stream" || v === "ref" || v === "deref" || v === "swap" || v === "atomic" || v === "emit" || v === "substrate");
}

function checkServerEffectResult(v: JsonValue | undefined): boolean {
  return (isRecord(v) && checkServerEffectKind(v["effect"]) && (v["action"] === undefined || typeof v["action"] === 'string') && (v["entityType"] === undefined || typeof v["entityType"] === 'string') && (v["name"] === undefined || v["name"] !== undefined) && (v["data"] === undefined || (v["data"] !== undefined || v["data"] !== undefined || v["data"] !== undefined)) && typeof v["success"] === 'boolean' && (v["denied"] === undefined || v["denied"] === true) && (v["error"] === undefined || typeof v["error"] === 'string') && (v["code"] === undefined || checkServerEffectCode(v["code"])) && (v["target"] === undefined || typeof v["target"] === 'string') && (v["routed"] === undefined || typeof v["routed"] === 'string'));
}

function checkTransitionHop(v: JsonValue | undefined): boolean {
  return (isRecord(v) && typeof v["trait"] === 'string' && typeof v["from"] === 'string' && typeof v["to"] === 'string' && typeof v["event"] === 'string' && (v["firedArm"] === undefined || typeof v["firedArm"] === 'number') && (v["guardResult"] === undefined || typeof v["guardResult"] === 'boolean') && (Array.isArray(v["effects"]) && v["effects"].every((e) => checkHopEffect(e))) && (v["observed"] === undefined || checkHopObservation(v["observed"])));
}

function checkTransitionRejection(v: JsonValue | undefined): boolean {
  return (isRecord(v) && checkTransitionRejectionCode(v["code"]) && (v["trait"] === undefined || typeof v["trait"] === 'string') && (v["from"] === undefined || typeof v["from"] === 'string') && (v["event"] === undefined || typeof v["event"] === 'string') && (v["statesDeclaringEvent"] === undefined || (Array.isArray(v["statesDeclaringEvent"]) && v["statesDeclaringEvent"].every((e) => typeof e === 'string'))) && (v["transition"] === undefined || typeof v["transition"] === 'string') && (v["guard"] === undefined || v["guard"] !== undefined) && (v["error"] === undefined || typeof v["error"] === 'string'));
}

function checkTransitionRejectionCode(v: JsonValue | undefined): boolean {
  return (v === "no-matching-transition" || v === "guard-rejected" || v === "no-dispatchable-traits" || v === "not-an-external-input" || v === "inbound-only-event" || v === "effect-failed");
}

/** The check of a kernel response at the host boundary: every field of `EventResponse` and of the wire types nested in it. */
export function isEventResponse(value: JsonValue): value is JsonValue & EventResponse {
  return checkEventResponse(value);
}
